corrected_code:
class TenantFeatureSettings(BaseSettings):
    enable_beta_ai: bool = False
    max_export_rows: int = 1000
    debug_tracing: bool = False

@app.post("/api/v1/tenants/{org_slug}/features/override")
def update_tenant_features(
    org_slug: str,
    overrides: TenantFeatureSettings,
    store: FeatureStore = Depends(get_feature_store),
    current_user: User = Depends(get_current_user)
):
    if current_user.org_slug != org_slug or not current_user.is_org_admin:
        raise HTTPException(status_code=403, detail="Forbidden: Insufficient privileges for target organization")
    store.save_overrides(org_slug, overrides.model_dump())
    return {"status": "updated", "org_slug": org_slug, "settings": overrides.model_dump()}
